// cap-widget.bridge.directive.ts
import { Directive, EventEmitter, Output, ElementRef, OnDestroy, AfterViewInit } from '@angular/core';

@Directive({
  selector: 'cap-widget' // greift auf das Web Component
})
export class CapWidgetBridgeDirective implements AfterViewInit, OnDestroy {
  @Output() solve  = new EventEmitter<CustomEvent<{ token: string }>>();
  @Output() error  = new EventEmitter<CustomEvent>();
  @Output() reset  = new EventEmitter<CustomEvent>();
  // falls du progress brauchst:
  @Output() progress = new EventEmitter<CustomEvent<{ value: number }>>();

  private el: HTMLElement;
  private handlers = new Map<string, any>();

  constructor(ref: ElementRef<HTMLElement>) { this.el = ref.nativeElement; }

  ngAfterViewInit() {
    this.on('solve',   (e: Event) => this.solve.emit(e as CustomEvent));
    this.on('error',   (e: Event) => this.error.emit(e as CustomEvent));
    this.on('reset',   (e: Event) => this.reset.emit(e as CustomEvent));
    this.on('progress',(e: Event) => this.progress.emit(e as CustomEvent));
  }

  ngOnDestroy() {
    for (const [type, h] of this.handlers) this.el.removeEventListener(type, h);
    this.handlers.clear();
  }

  private on(type: string, handler: (e: Event) => void) {
    this.handlers.set(type, handler);
    this.el.addEventListener(type, handler as EventListener);
  }
}
