// src/app/cap-widget.component.ts
import {
  Component,
  Input,
  OnDestroy,
  AfterViewInit,
  inject,
  CUSTOM_ELEMENTS_SCHEMA, PLATFORM_ID, signal
} from '@angular/core';
import { CommonModule, isPlatformBrowser } from '@angular/common';
import {ToastService} from '../../services/toast.service';
import {CaptchaService} from '../../services/captcha.service';
import {CapWidgetBridgeDirective} from './cap-widget.bridge.directive';
import {LoggerService} from '../../services/logger.service';
import {ProfileService} from '../../services/profile.service';

import('@cap.js/widget');

@Component({
  selector: 'app-cap-widget',
  standalone: true,
  imports: [CommonModule, CapWidgetBridgeDirective],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
  templateUrl: './cap-widget.component.html',
  styleUrls: ['./cap-widget.component.css'],
})
export class CapWidgetComponent implements AfterViewInit, OnDestroy {
  @Input({ required: true }) apiEndpoint!: string;
  @Input() apiVerifyUrl: string = '/captcha/verify';
  @Input() showReset = false;

  // optionale deutsche Labels
  @Input() i18nInitial   = 'Ich bin ein Mensch';
  @Input() i18nVerifying = 'Wird geprüft…';
  @Input() i18nSolved    = 'Remoteprüfung';
  @Input() i18nError     = 'Fehler';

  token_in_flight= ''

  verified = false;
  widgetKey = 0;
  private platformId = inject(PLATFORM_ID);

  constructor(private toast: ToastService, private captcha: CaptchaService, private profile: ProfileService, private log: LoggerService) {
    this.profile.profile$.subscribe(profile => {
      this.verified = profile.is_human
    })
  }

  async ngAfterViewInit() {
    this.captcha.apiVerifyUrl = this.apiVerifyUrl;

    // SSR-Safe: nur im Browser laden
    if (!isPlatformBrowser(this.platformId)) return;
  }

  ngOnDestroy() {}

  onSolve(e: CustomEvent<{ token: string}>) {
    const token = e.detail?.token;
    if (!token) return;
    if (this.token_in_flight == token) {
      return;
    }
    this.token_in_flight = token;
    this.captcha.verifyTokenOnBackend(token).subscribe({
      complete: () => {
        this.profile.reloadRequired = true
        this.log.log('verifyTokenOnBackend completed')
      },
      error: err => {
        this.log.log(`verifyTokenOnBackend error: ${err}`)
      }
    })
  }

  onError(_e:Event) {
    this.toast.add('Fehler', 'CapJS: error event erhalten', 'error')
    this.log.error('CapJS: error event erhalten');
  }

  /** Manuelles Zurücksetzen (z. B. für Tests oder Logout) */
  reset() {
    this.captcha.reset();
    this.widgetKey++;
    this.verified = false;
  }
}
