import {inject, Injectable} from '@angular/core';
import { HttpClient } from '@angular/common/http';
import {ToastService} from './toast.service';
import {LoggerService} from './logger.service';
import {catchError} from 'rxjs/operators';
import {throwError} from 'rxjs';

@Injectable({ providedIn: 'root' })
export class CaptchaService {
  private toast = inject(ToastService);
  private tokenKey = 'cap.token';
  private verifiedKey = 'cap.verified';
  apiVerifyUrl = '/api/auth/captcha/verify-will-be-defined-in-form/';

  constructor(private http: HttpClient, private log: LoggerService) {}

  verifyTokenOnBackend(token: string) {
    this.log.log(`Verify token on backend ${this.apiVerifyUrl}`)
    return this.http.post<Boolean>(this.apiVerifyUrl,
      { token: token },
      { withCredentials: true }).pipe(
        catchError((err) => {
          this.toast.add('Fehler bei Prüfung', err || 'Unbekannter Fehler bei Token Prüfung', 'error');
          this.reset()
          return throwError(() => err);
      })
  )}

  reset() {
    localStorage.removeItem(this.tokenKey);
    localStorage.setItem(this.verifiedKey, 'false');
  }
}
