import {CommonModule} from '@angular/common';
import {TvzApiService} from '../../services/tvz-api.service';
import {Component, inject, OnDestroy, OnInit} from '@angular/core';
import {FormsModule} from '@angular/forms';
import {GeolocationService} from '../../services/geolocation.service';
import {Venue} from '../../models/venue.model';
import {Game} from '../../models/game.model';
import {SearchClubVenueComponent} from '../../components/search-club-venue/search-club-venue.component';
import {GameDetailPageComponent} from '../game-detail-page/game-detail-page.component';
import {AdsenseComponent} from '../../components/adsense/adsense.component';
import {BoostComponent} from '../../components/boost/boost.component';
import {GeolocationCoordinates} from '../../models/geolocation.models';
import {GameViewComponent} from '../../components/game-view/game-view.component';
import {BehaviorSubject, Observable} from 'rxjs';
import {DebugComponent} from '../../components/debug/debug.component';
import {environment} from '../../../environments/environment';

@Component({
  standalone: true,
  selector: 'app-game-vote',
  templateUrl: './game-vote-page.component.html',
  imports: [CommonModule, FormsModule, SearchClubVenueComponent, GameDetailPageComponent, AdsenseComponent, BoostComponent, GameViewComponent, DebugComponent],
})
export class GameVotePageComponent implements OnInit, OnDestroy {
  private api = inject(TvzApiService);
  protected geo = inject(GeolocationService);

  loadingLogin = false;
  loadingGame = false;
  venues: Venue[] = [];
  currentLocation: GeolocationCoordinates | undefined
  _selectedVenue: Venue | undefined;
  closestVenues: {venue: Venue, distance: number}[] = [];
  games: Game[] = [];
  filteredGames: Game[] = [];
  selectedGame: Game | null = null;
  manuallyDeselected: boolean = false;

  showPast$ = new BehaviorSubject(true);
  showFuture$ = new BehaviorSubject(true);


  get selectedVenue(): Venue | undefined {
    return this._selectedVenue;
  }

  set selectedVenue(value: Venue | undefined) {
    this._selectedVenue = value;
    this.loadingGame = true;
    if (value) {
      this.api.getGames({
        club: undefined,
        venue: value.venueId ?? undefined,
        season: this.api.getSeasonId() ?? undefined
      }).subscribe(games => {
        this.games = games.sort((a, b) => new Date(a.gameDateTime).getTime() - new Date(b.gameDateTime).getTime());
        this.filteredGames = games;
        const now = new Date();
        const endedRecently = this.games.filter(g => {
          const end = new Date(g.gameDateTime);
          return end >= new Date(now.getTime() - 120 * 60 * 1000) && end <= now;
        });
        const upcoming = games.filter(g => new Date(g.gameDateTime) > now);

        if (endedRecently.length > 0) {
          // Spiel, das kürzlich geendet hat, wählen (das letzte davon)
          this.selectedGame = endedRecently[endedRecently.length - 1];
        } else if (upcoming.length > 0) {
          // Das nächste geplante Spiel
          this.selectedGame = upcoming[0];
        } else {
          this.selectedGame = null;
        }
        this.loadingGame = false;
      });
    }
  }

  ngOnInit() {
    this.loadingLogin = true;
    this.api.getVenues().subscribe( venues => {
      this.venues = venues;
      this.findClosestVenue()
    })
    this.geo.locationAllowed$.subscribe((val) => {
      if (val) {
        this.findClosestVenue();
      }
    })
    this.geo.startTracking((location) => {
      if (location) {
        this.currentLocation = location.coords;
        this.findClosestVenue();
      }
    });
    this.showFuture$.subscribe((val) => {
      const showPast = this.showPast$.value
      const showFuture = val
      this.filteredGames = this.games.filter(g => {
        const today = new Date().getTime();
        const date = new Date(g.gameDateTime).getTime();
        const isPast = date < today;
        const isToday = date == today;
        const isFuture = date > today;
        return (showPast && isPast) || isToday || (showFuture && isFuture);
      }).sort((a, b) => new Date(a.gameDateTime).getTime() - new Date(b.gameDateTime).getTime());
    })
    this.showPast$.subscribe((val) => {
      const showPast = val
      const showFuture = this.showFuture$.value
      this.filteredGames = this.games.filter(g => {
        const today = new Date().getTime();
        const date = new Date(g.gameDateTime).getTime();
        const isPast = date < today;
        const isToday = date == today;
        const isFuture = date > today;
        return (showPast && isPast) || isToday || (showFuture && isFuture);
      }).sort((a, b) => new Date(a.gameDateTime).getTime() - new Date(b.gameDateTime).getTime());
    })
  }

  ngOnDestroy() {
    this.geo.stopTracking();
    this.showFuture$.complete();
    this.showPast$.complete();
  }

  private findClosestVenue() {
    if (this.currentLocation !== undefined) {
      this.closestVenues = this.venues
        .map( venue => {
          const hasCoords = venue?.venueLat && venue?.venueLon;
          const distance = hasCoords ? this.geo.getDistance(
            {lat: this.currentLocation?.latitude!, lon: this.currentLocation?.longitude!},
              {
              lat: +venue.venueLat,
              lon: +venue.venueLon
            })
            : Number.MAX_VALUE;
          return { venue, distance };
        })
        .sort((a, b)=> {
          return a.distance - b.distance;
        }).slice(0, 3) ?? [];
      if (!this._selectedVenue && this.closestVenues.length > 0) {
        if (!this.manuallyDeselected) {
          this.selectedVenue = this.closestVenues[0].venue;
        }
      }
    }
  }

  togglePast(): void {
    this.showPast$.next(!this.showPast$.value);
  }

  toggleFuture(): void {
    this.showFuture$.next(!this.showFuture$.value);
  }

  venueSelected(data?: { venue?: Venue | undefined; }): void {
    this.selectedVenue = data?.venue
  }

  protected readonly environment = environment;
}
