import {Component, inject, signal} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {CapWidgetComponent} from '../cap-widget/cap-widget.component';
import {ProfileService} from '../../services/profile.service';
import {Profile} from '../../models/profile.model';
import {environment} from '../../../environments/environment';

@Component({
  standalone: true,
  selector: 'app-boost',
  templateUrl: './boost.component.html',
  imports: [CommonModule, FormsModule, CapWidgetComponent]
})
export class BoostComponent {
  private profileService = inject(ProfileService);

  profile: Profile|undefined
  isHuman = false;
  locationEnabled = false;
  factor = 0;
  boostMax = 0;
  humanVisible = false;
  detailsVisible= signal(true);
  protected verifyUrl: string;

  toggle() {
    this.detailsVisible.update((visible) => !visible);
  }

  constructor() {
    this.verifyUrl = environment.apiHost;
    this.profileService.profile$.subscribe((profile) => {
      this.profile = profile;
      this.isHuman = this.profile.is_human
      this.locationEnabled = this.profile.location_enabled
      this.boostMax = this.profile.weight.max
      this.factor = this.profile.weight.value
      this.detailsVisible.set(this.profile.weight.value == 0 || this.profile.weight.max != this.profile.weight.value)
    })
  }
}
