import {Injectable} from '@angular/core';
import {BehaviorSubject, firstValueFrom, Observable} from 'rxjs';
import {Profile} from '../models/profile.model'
import {HttpClient} from '@angular/common/http';
import { catchError } from 'rxjs/operators';
import {LoggerService} from './logger.service';
import {GeolocationService} from './geolocation.service';
import {CaptchaService} from './captcha.service';
import {environment} from '../../environments/environment';

@Injectable({ providedIn: 'root' })
export class ProfileService {

  profile$ = new BehaviorSubject<Profile>({
    location_enabled: false,
    is_human: false,
    weight: { value: 0, max: 0 }
  });
  private baseUrl = `${environment.apiHost}/api`;
  private baseUrl_v1 = `${this.baseUrl}/v1.0`;
  reloadRequired = true
  profileChanged = false

  constructor(private http: HttpClient, private log: LoggerService, private geo: GeolocationService, private captcha: CaptchaService) {
    this.log.log('profile in constructor');

    // reload loop
    setInterval(() => {
      if (this.reloadRequired) {
        this.reloadRequired = false;
        this.reloadProfile()
      }
      if (this.profileChanged) {
        this.profileChanged = false
        this.postProfile(this.profile$.value).subscribe(profile => {
          this.log.log(`posted profile, got result ${profile}`)
          this.profile$.next(profile);
        })
      }
    }, 200);

    // update location_enabled
    this.geo.locationAllowed$.subscribe(location_allowed => {
      this.log.log(`location allowed ${location_allowed}`);
      if (this.profile$.value.location_enabled != location_allowed) {
        const p = this.profile$.value;
        p.location_enabled = location_allowed;
        this.profile$.next(p);
        this.profileChanged = true;
      }
    })
    this.geo.startTracking((location) => {
      const loc = JSON.stringify(location);
      this.log.log(`got location update: ${loc}`);
    })
  }

  private reloadProfile() {
    this.getProfile().then(profile => {
      if (profile) {
        this.profile$.next(profile);
      }
    })
  }

  postProfile(profile: Profile):Observable<Profile> {
    return this.http.post<Profile>(
      `${this.baseUrl}/auth/profile/`,
      profile,
      {
        withCredentials: true,
        responseType: "json"
      }).pipe(
      catchError(err => {
        this.log.error(err)
        throw err;
      })
    )
  }

  async getProfile(): Promise<Profile|undefined> {
    const response = await firstValueFrom(
      this.http.get<{ profile: any; errors?: any[] }>(
        `${this.baseUrl}/auth/profile/`,
        { withCredentials: true }
      ).pipe(
        catchError(err => {
          this.log.error(err)
          throw err;
        })
      )
    );

    const { profile, errors } = response;

    if (errors?.length) {
      this.log.error(errors);
      return;
    }
    return profile;
  }
}
