import {
  Component, inject,
  OnDestroy,
  OnInit
} from '@angular/core';
import {CommonModule} from '@angular/common';
import {FormsModule} from '@angular/forms';
import {GeolocationService} from '../../services/geolocation.service';
import {LoggerService} from '../../services/logger.service';
import {ProfileService} from '../../services/profile.service';
import {Profile} from '../../models/profile.model';
import {TokenAuthService} from '../../services/token.service';
import {switchMap} from 'rxjs';


@Component({
  standalone: true,
  selector: 'app-debug',
  templateUrl: './debug.component.html',
  imports: [CommonModule, FormsModule]
})
export class DebugComponent implements OnInit, OnDestroy {
  protected locationAllowed = false;
  protected position: GeolocationPosition|undefined;
  protected profile: Profile|undefined

  constructor(private geo: GeolocationService, private profileService: ProfileService, protected token: TokenAuthService, private log: LoggerService) {
    this.geo.locationAllowed$.subscribe(location => {
      this.locationAllowed = location;
    })
  }

  refreshToken() {
    this.token.refreshAccessToken().subscribe(() => {})
  }

  ngOnInit() {
    this.geo.startTracking((position, error) => {
      this.position = position;
    })
    this.profileService.profile$.subscribe(profile => {
      this.profile = profile;
    })
  }

  ngOnDestroy() {
    this.geo.stopTracking()
  }

  protected readonly location = location;
}
